// Short titles for sessions that never got one (Claude app bridge, terminal),
// generated by Haiku in an isolated, tool-less, non-persisted query.
import { query } from '@anthropic-ai/claude-agent-sdk'
import { config } from './config.ts'
import { save, state } from './store.ts'

const queue: { id: string; prompt: string }[] = []
const queued = new Set<string>()
const failedAt = new Map<string, number>()
let running = false

export function requestTitle(id: string, prompt: string | undefined) {
  if (!prompt?.trim() || state.titles[id] || queued.has(id)) return
  if (Date.now() - (failedAt.get(id) ?? 0) < 30 * 60_000) return
  queued.add(id)
  queue.push({ id, prompt })
  if (!running) void drain()
}

async function drain() {
  running = true
  while (queue.length) {
    const job = queue.shift()!
    try {
      const title = await generate(job.prompt)
      if (title) {
        state.titles[job.id] = title
        save()
      } else failedAt.set(job.id, Date.now())
    } catch {
      failedAt.set(job.id, Date.now())
    } finally {
      queued.delete(job.id)
    }
  }
  running = false
}

async function generate(prompt: string): Promise<string | undefined> {
  const abort = new AbortController()
  const timer = setTimeout(() => abort.abort(), 45_000)
  const q = query({
    prompt: `为下面这条请求起一个会话标题。只输出标题本身：中文为主，4 到 14 个字，概括要做的事，不要引号和句号。\n\n${prompt.slice(0, 800)}`,
    options: {
      model: 'haiku',
      cwd: config.defaultCwd,
      pathToClaudeCodeExecutable: config.claudePath,
      persistSession: false,
      settingSources: [],
      tools: [],
      maxTurns: 1,
      systemPrompt: 'You write short chat titles.',
      abortController: abort,
    },
  })
  try {
    for await (const m of q as AsyncIterable<any>) {
      if (m.type === 'result') {
        const text: string = m.subtype === 'success' ? m.result ?? '' : ''
        const line = text.split(/[\r\n\u2028]+/).map((l) => l.trim()).find(Boolean) ?? ''
        return line.replace(/^["“「『#]+|["”」』。.]+$/g, '').replace(/\s+/g, ' ').trim().slice(0, 30) || undefined
      }
    }
  } finally {
    clearTimeout(timer)
    q.close()
  }
  return undefined
}
